mapper.select:
SELECT A.SUP_FREQUENCY as supFrequency, W.FREQUENCY as frequency, A.PORTFOLIO_ID, A.IND_ID as indId, B.IND_NAME as indName, B.SUP_TYPE as supType, A.SUP_DATE as supDate, A.SUP_VAL AS supVal, A.WARN_COND as warnCond, A.APPROVE_COND as approveCond, A.FOUL_COND as foulCond, A.SUP_STAT as supStat, A.FOUL_DAYS as foulDays, A.SUP_UNITE_STAT as supUniteStat, A.MATH_PROCESS as mathProcess, B.MEMO as memo, B.IND_TYPE as indType, (CASE WHEN C.PORTFOLIO_LEVEL = #{PORTFOLIO_LEVEL_01,jdbcType = VARCHAR} THEN (SELECT D.PORTFOLIO_NAME FROM PTL_PORTFOLIO D WHERE D.PORTFOLIO_ID = A.PORTFOLIO_ID) ELSE (SELECT E.PTL_BAG_NAME FROM RSK_PORTFOLIO_PACKAGE E WHERE E.PTL_BAG_ID = A.PORTFOLIO_ID) END ) groupName, (SELECT count(1) FROM RSK_ISUP_POINT_DET_VAL t WHERE t.IND_ID=A.IND_ID AND T.PORTFOLIO_ID=A.PORTFOLIO_ID AND T.SUP_FREQUENCY=A.SUP_FREQUENCY AND T.SUP_DATE=A.SUP_DATE) AS mxCount FROM RSK_ISUP_POINT_VAL A INNER JOIN RSK_PORTFOLIO_INDICATOR C ON C.PORTFOLIO_ID = A.PORTFOLIO_ID AND C.IND_ID = A.IND_ID INNER JOIN RSK_ISUP_INDICATOR B ON B.IND_ID = A.IND_ID LEFT JOIN PTL_PORTFOLIO D ON D.PORTFOLIO_ID = A.PORTFOLIO_ID LEFT JOIN RSK_PORTFOLIO_PACKAGE E ON E.PTL_BAG_ID = A.PORTFOLIO_ID LEFT JOIN (select A.PORTFOLIO_ID AS ID,COUNT(A.SUP_STAT) AS frequency from RSK_ISUP_POINT_VAL A
A.SUP_STAT <> 'NORMAL'
AND TO_CHAR(A.SUP_DATE,'yyyy-MM-dd') >= #{starSupDate}
AND TO_CHAR(A.SUP_DATE,'yyyy-MM-dd') <= #{endSupDate}
group by A.PORTFOLIO_ID) W ON W.ID = A.PORTFOLIO_ID INNER JOIN ( SELECT A.PORTFOLIO_ID, A.IND_ID, A.SUP_DATE, MAX(A.UPDATE_TIME) AS updateTime FROM RSK_ISUP_POINT_VAL A GROUP BY A.PORTFOLIO_ID, A.IND_ID, A.SUP_DATE) M ON A.UPDATE_TIME = M.updateTime AND M.PORTFOLIO_ID = A.PORTFOLIO_ID AND M.IND_ID = A.IND_ID AND M.SUP_DATE = A.SUP_DATE
AND B.IND_NAME LIKE CONCAT(CONCAT('%',#{indName}),'%')
AND ( D.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{groupName}),'%')
OR D.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{groupName}),'%')
OR E.PTL_BAG_NAME LIKE CONCAT(CONCAT('%',#{groupName}),'%')
OR E.PTL_BAG_ID LIKE CONCAT(CONCAT('%',#{groupName}),'%'))
AND B.SUP_TYPE = #{supType}
AND A.SUP_STAT = #{supStat}
AND TO_CHAR(A.SUP_DATE,'yyyy-MM-dd') >= #{starSupDate}
AND TO_CHAR(A.SUP_DATE,'yyyy-MM-dd') <= #{endSupDate}
AND (case when A.SUP_UNITE_STAT is null then A.SUP_STAT else A.SUP_UNITE_STAT end) <> #{infParam, jdbcType=VARCHAR}
AND ( D.PORTFOLIO_ID in (select PORTFOLIO_ID from FIN_PRODUCT_ADD where PROD_MANAGER in
#{item}
) or E.PTL_BAG_ID in (select PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL where PORTFOLIO_ID in (select PORTFOLIO_ID from FIN_PRODUCT_ADD where PROD_MANAGER in
#{item}
) ) )
ORDER BY A.SUP_DATE DESC

SELECT DISTINCT A.PORTFOLIO_ID portfolioId, A.IND_ID indId, B.IND_NAME indName, A.ASSET_CODE assetCode, B.SUP_TYPE supType, A.SUP_DATE supDate, A.SUP_VAL supVal, A.SUP_STAT supStat, D.WARN_COND warnCond, D.APPROVE_COND approveCond, D.FOUL_COND foulCond, B.IND_TYPE indType, NVL(A.ASSET_NAME,E.FINPROD_NAME) assetName FROM RSK_ISUP_POINT_DET_VAL A INNER JOIN RSK_PORTFOLIO_INDICATOR C ON C.PORTFOLIO_ID = A.PORTFOLIO_ID AND C.IND_ID = A.IND_ID INNER JOIN RSK_ISUP_INDICATOR B ON B.IND_ID = A.IND_ID INNER JOIN RSK_ISUP_POINT_VAL D ON D.IND_ID = A.IND_ID and D.PORTFOLIO_ID=A.PORTFOLIO_ID and D.SUP_DATE=A.SUP_DATE LEFT JOIN FIN_PRODUCT E ON A .ASSET_CODE = E.FINPROD_ID
A.IND_ID =#{indId}
AND A.PORTFOLIO_ID =#{portfId}
AND TO_CHAR(A.SUP_DATE,'yyyy-MM-dd') = #{supDate}
AND A.SUP_FREQUENCY = #{supFrequency}

select * from ( SELECT A.PORTFOLIO_ID portfolioId, A.IND_ID indId, B.IND_NAME indName, B.SUP_TYPE supType, A.SUP_DATE supDate, A.SUP_VAL supVal, A.SUP_STAT supStat, A.WARN_COND warnCond, A.APPROVE_COND approveCond, A.FOUL_COND foulCond, B.IND_TYPE indType FROM RSK_ISUP_POINT_VAL A INNER JOIN RSK_ISUP_INDICATOR B ON A.IND_ID = B.IND_ID
AND A.IND_ID =#{indId}
AND A.PORTFOLIO_ID =#{portfId}
AND A.SUP_DATE <=to_date(#{supDate},'yyyy-MM-dd')
AND A.SUP_FREQUENCY =#{supFrequency}
AND A.SUP_STAT='VIOLATION' ORDER BY A.SUP_DATE DESC
) where rownum <= ${foulDays}

SELECT DISTINCT A.PORTFOLIO_ID portfolioId, (nvl(A.MARKET_VALUE,0)+nvl(A.TDY_INTINCEXP,0)) shareAmt, B.PORTFOLIO_NAME portfolioName, NVL(E.FINPROD_ID,F.ASSET_CODE) assetCode, G.PROD_MANAGER invManagerId, NVL(E.FINPROD_NAME,F.ASSET_NAME) assetName FROM ( SELECT * FROM PTL_SEC_PIERCE_VALUTION
AND FINPROD_ID=#{assetCode}
AND CDATE = to_date(#{supDate},'yyyy-MM-dd')
AND PORTFOLIO_ID in
#{item}
) A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN (SELECT FINPROD_NAME,FINPROD_ID FROM FIN_PRODUCT
FINPROD_ID=#{assetCode}
) E ON E.FINPROD_ID = A.FINPROD_ID INNER JOIN RSK_ISUP_POINT_DET_VAL F ON F.ASSET_NAME = E.FINPROD_NAME LEFT JOIN FIN_PRODUCT_ADD G ON G.FINPROD_ID = A.PORTFOLIO_ID
F.ASSET_NAME =#{assetName}

SELECT distinct SYS_USER.USER_NAME as id, SYS_USER.REAL_NAME as text FROM SYS_USER INNER JOIN SYS_USER_ROLE ON SYS_USER.USER_NAME = SYS_USER_ROLE.USER_ID INNER JOIN SYS_ROLE ON SYS_ROLE.ROLE_ID = SYS_USER_ROLE.ROLE_ID
AND SYS_ROLE.ROLE_POS = #{roleName,jdbcType=VARCHAR}
where 1=1
AND (SYS_USER.USER_NAME like concat(concat('%',#{search}),'%') or SYS_USER.REAL_NAME like concat(concat('%',#{search}),'%') )
and SYS_USER.USER_NAME = #{initValue}
